package com.hospital.dao;
import com.hospital.util.DBConnection;import java.sql.*;import java.util.*;
public class PrescriptionDAO {
 public long create(long record,List<String[]> items,long doctor)throws SQLException{if(items.isEmpty())throw new IllegalArgumentException("Add at least one medicine.");try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{long id;try(PreparedStatement p=c.prepareStatement("INSERT INTO prescriptions(record_id) SELECT record_id FROM medical_records WHERE record_id=? AND doctor_id=?",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,record);p.setLong(2,doctor);if(p.executeUpdate()==0)throw new SQLException("Medical record not found or not assigned to your doctor account.");try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getLong(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO prescription_items(prescription_id,medicine_name,dosage,frequency,duration,instructions) VALUES(?,?,?,?,?,?)")){for(String[] i:items){p.setLong(1,id);for(int n=0;n<5;n++)p.setString(n+2,i[n]);p.addBatch();}p.executeBatch();}c.commit();return id;}catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
 public List<String> list(long patient,Long doctor)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT pr.prescription_id,pi.medicine_name,pi.dosage,pi.frequency,pi.duration,pi.instructions FROM prescriptions pr JOIN medical_records mr USING(record_id) JOIN prescription_items pi USING(prescription_id) WHERE mr.patient_id=? AND (? IS NULL OR mr.doctor_id=?) ORDER BY pr.prescription_id DESC")){p.setLong(1,patient);if(doctor==null){p.setNull(2,Types.BIGINT);p.setNull(3,Types.BIGINT);}else{p.setLong(2,doctor);p.setLong(3,doctor);}try(ResultSet r=p.executeQuery()){List<String>x=new ArrayList<>();while(r.next())x.add(String.format("Rx %d | %s %s | %s | %s | %s",r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)));return x;}}}
}
